// L leg -- SCR-121 CHECKMULTISIG is banned in tapscript (BIP342).
//
// REVIEWED TRANSLITERATION of the first line of
// Bitcoin.Interpreter.Defs.checkMultiSig
// (spec/core/Bitcoin/Interpreter/Defs.lean:1071-1073):
//
//   checkMultiSig ctx w st :=
//     if ctx.sv = .tapscript then .error .tapscriptCheckMultiSig
//     else if st.stack.length < 1 then .error .stackUnderflow
//     ...  (front matter reproduced so the ban is not over-applied)
//
// plus the rule tag `BitcoinProofs.AF.PDW73.stepBody_tapscript_checkmultisig_ban`.
// NOT generated by twin/gen.py (no CHECKMULTISIG handler in twin/ops_ir.py).
// `.tapscriptCheckMultiSig` is `SCRIPT_ERR_TAPSCRIPT_CHECKMULTISIG`, ordinal 50
// in contract/error_kind.h.
//
// SigVersion encoding: 0 = base, 1 = witnessV0, 2 = tapscript (Lean's
// three-constructor `SigVersion`; other inputs are not engine-reachable).
#include <cstdint>
#include "cms_obs.h"

enum {
  BAN_OK = 0,
  BAN_PUBKEY_COUNT = 1,
  BAN_OP_COUNT = 2,
  BAN_UNDERFLOW = 3,
  BAN_SIG_COUNT = 4
};

extern "C" uint64_t cell_cms_tapscript_ban(uint32_t sigversion, uint32_t opcode,
                                           uint32_t stackSize, int32_t nKeysIn,
                                           int32_t nSigsIn) {
  (void)opcode;
  if (sigversion == 2u) {                    // ctx.sv = .tapscript
    return cms_pack6(CMS_TAPSCRIPT_CHECKMULTISIG, 0, 0, 0, 0);
  }
  const uint64_t depth = (uint64_t)stackSize;
  if (depth < 1u) return cms_pack6(BAN_UNDERFLOW, 0, 0, 0, 0);
  const int64_t nkv = (int64_t)nKeysIn;
  if (nkv < 0 || 20 < nkv) return cms_pack6(BAN_PUBKEY_COUNT, 0, 0, 0, 0);
  const uint32_t nKeys = (uint32_t)nkv;
  const int64_t ikey2 = (int64_t)nKeys + 2;
  if (depth < (uint64_t)nKeys + 2u) return cms_pack6(BAN_UNDERFLOW, 0, 0, 0, 0);
  const int64_t nsv = (int64_t)nSigsIn;
  if (nsv < 0 || nkv < nsv) return cms_pack6(BAN_SIG_COUNT, 0, 0, 0, 0);
  const uint32_t nSigs = (uint32_t)nsv;
  if (depth < (uint64_t)nKeys + (uint64_t)nSigs + 3u) {
    return cms_pack6(BAN_UNDERFLOW, 0, 0, 0, 0);
  }
  return cms_pack6(BAN_OK, nKeys, nSigs, (uint32_t)ikey2, nKeys + 3u);
}
